from copy import deepcopy
def solve(I,kmin=2):
    H,W=len(I),len(I[0]); bg=max(map(max,I))
    S={(r,c) for r in range(H) for c in range(W) if I[r][c]!=bg and I[r][c]!=0}
    sig=I[next(iter(S))[0]][next(iter(S))[1]]
    painted=S
    def neigh(p):
        rr,cc=p
        return [(rr+a,cc+b) for a in(-1,0,1) for b in(-1,0,1) if (a,b)!=(0,0)]
    while True:
        added=[]
        for p in [(r,c) for r in range(H) for c in range(W) if (r,c) not in painted]:
            nb=sum(1 for q in neigh(p) if q in painted)
            if nb>=kmin: added.append(p)
        if not added: break
        painted|={p for p in added if I[p[0]][p[1]]==0}
    return [[sig if (r,c) in painted else (0 if I[r][c]==0 else I[r][c]) for c in range(W)] for r in range(H)]
